{
  "name": "pairwise_advantage_gap_loss",
  "intuition": "This loss encourages the model to increase the advantage difference between preferred and less preferred options by focusing on the advantage gap. By maximizing advantage_gap (or equivalently minimizing its negative), it aligns the model towards preferred outcomes, promoting better ranking and preference consistency.",
  "pseudocode": "Loss = -mean(logsigmoid(advantage_w - advantage_l + margin))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "margin=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    margin = extra.get('margin', 1.0)\n    diff = ops.sub(advantage_w, advantage_l)\n    loss_terms = ops.logsigmoid(ops.add(diff, margin))\n    weighted_loss = ops.mul(loss_terms, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "loss_advantage_tanh_contrastive",
  "intuition": "Contrastive loss paradigm using a smooth bounded tanh of the advantage difference to enforce margin and stability, emphasizing preference ranking with a symmetric structured penalty rather than a simple margin.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nscaled_diff = alpha * adv_diff\nclamped = clamp(scaled_diff, -10, 10)\nloss = mean(1 - tanh(clamped)) weighted by example weight",
  "hyperparams": {
    "paradigm_family": "contrastive",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "clamp_bounded"
  },
  "operators_used": ["tanh", "clamp", "mean", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled_diff = ops.mul(alpha, adv_diff)\n    clamped = ops.clamp(scaled_diff, -10.0, 10.0)\n    raw_loss = ops.sub(ops.ones_like(clamped), ops.tanh(clamped))\n    if weight is not None:\n        raw_loss = ops.mul(raw_loss, weight)\n    return ops.mean(raw_loss)"
}

{
  "name": "mixed_logsigmoid_cost_logsigmoid",
  "intuition": "Combine the stable pairwise logsigmoid losses with different scales to balance their influence effectively. Using the higher scale from parent 0 emphasizes larger margins, while the lower scale from parent 1 preserves sensitivity. Incorporating both allows the model to learn a nuanced cost gap metric while maintaining numerical stability and pass semantics. The combined loss takes a weighted average of the two, leveraging their proven stability and semantic pass constraints.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    # Retrieve hyperparams for parent 0\n    scale0 = float(extra.get('hyperparams0', {}).get('scale', 1.9496803035382082))\n    # Retrieve hyperparams for parent 1\n    scale1 = float(extra.get('hyperparams1', {}).get('scale', 0.6752757766189963))\n    # Compute individual loss components\n    x0 = alpha * scale0 * (lpw - lpl)\n    x1 = alpha * scale1 * (lpw - lpl)\n    # Stabilize with clamping\n    x0_clamped = ops.clamp(x0, -20.0, 20.0)\n    x1_clamped = ops.clamp(x1, -20.0, 20.0)\n    # Compute losses\n    loss0 = -ops.logsigmoid(x0_clamped)\n    loss1 = -ops.logsigmoid(x1_clamped)\n    # Combine losses (average)\n    combined_loss = (loss0 + loss1) * 0.5\n    # Apply weight if present\n    if weight is not None:\n        combined_loss = combined_loss * weight\n    return combined_loss.mean()",
