{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages preference signals based on advantage and cost gap, promoting better ranking of higher advantage and lower cost gaps. It weighs pairwise comparisons so that pairs with higher advantage and lower cost gap contribute positively, aligning the model to favor better outcomes. Using logsigmoid functions emphasizes significant differences while maintaining numerical stability.",
  "pseudocode": "loss = sum_logsigmoid( advantage_w - advantage_l + alpha * (cost_gap_w - cost_gap_l) ) / batch_size",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage_cost",
    "link_family": "pairwise",
    "agg_family": "log",
    "constraint_family": "margin",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid", "sub", "mul", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get('alpha', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap_w = batch['cost_gap']  # assumed batch['cost_gap'] for both; adjust if separate\n    cost_gap_l = batch.get('cost_gap', 0)\n    weight = batch['weight']\n    # Compute pairwise difference\n    diff_adv = ops.sub(advantage_w, advantage_l)\n    diff_cost = ops.mul(alpha, ops.sub(cost_gap_w, cost_gap_l))\n    combined = ops.add(diff_adv, diff_cost)\n    loss_vals = ops.logsigmoid(combined)\n    # Optionally weigh by pair weight\n    weighted_loss = ops.mul(loss_vals, weight)\n    # Return mean over batch\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_advantage_gap_loss",
  "intuition": "This loss leverages the advantage_gap signal to compare pairs' relative quality, encouraging the model to rank higher advantage scores higher, which aligns with the goal of preference optimization. Using the advantage_gap normalizes differences, improving stability across batch pairs.",
  "pseudocode": "loss = mean over pairs of logsigmoid( advantage_gap between pair )",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "identity",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_gap = batch['advantage_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    score_diff = advantage_gap\n    label = ops.sign(score_diff)\n    pairwise_term = ops.logsigmoid(ops.mul(score_diff, label))\n    weighted_loss = ops.mul(pairwise_term, weight)\n    loss = ops.mean(weighted_loss)\n    return loss"
}

