{
  "name": "pairwise_margin_rank_advantage",
  "intuition": "This loss compares the log probabilities of w and l, penalizing cases where the difference is less than a margin, weighted by the square root of the advantage gap. It promotes correct ranking by encouraging the preferred sample to have higher log probability, with the advantage gap emphasizing moderate differences for more effective learning.",
  "pseudocode": "diff = log_prob_w - log_prob_l\nhinge = max(0, margin - diff)\nweighting = sqrt(abs(advantage_gap))\nloss = weighting * hinge\nreturn mean(loss * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "linear",
    "agg_family": "mean",
    "constraint_family": "nonnegative"
  },
  "operators_used": ["max", "abs", "sqrt", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', None)\n    margin = float(extra.get('margin', 1.0))\n    diff = ops.sub(lpw, lpl)\n    zero = ops.zeros_like(diff)\n    hinge = ops.max(ops.sub(margin, diff), zero)\n    weighting = ops.sqrt(ops.abs(adv_gap))\n    loss = ops.mul(weighting, hinge)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

